DECLARE @HEADER NVARCHAR(MAX);
DECLARE @STYLE  NVARCHAR(MAX);
DECLARE @HTML   NVARCHAR(MAX);
DECLARE @SQL    NVARCHAR(MAX);

SELECT @HEADER = '<p><b>Control Date Summary:</b></p>';

SELECT @STYLE = '
<style>
    table {
        border-collapse: collapse;
        font-family: Aptos;
        font-size: 11pt;
    }
    th, td {
        text-align: left;
        padding: 5px;
        border: 1px solid #BFBFBF;
    }
    tr:nth-child(2n) {
        background-color: #D6EEEE;
    }
</style>';

SET @SQL = '
SELECT @HTML_OUT =
    ''<table>'' +
    ''<tr><th>SOURCE NAME</th><th>DATE</th></tr>'' +

    (
        SELECT STRING_AGG(
            ''<tr><td>'' + [SOURCE] + ''</td>'' +
            ''<td>'' + ISNULL(CONVERT(NVARCHAR(50), [DATE], 120), '''') + ''</td></tr>'',
            ''''
        )
        FROM
        (
            ' +

            (
                SELECT STRING_AGG(
                    CONCAT(
                        'SELECT ''', COLUMN_NAME, ''' AS [SOURCE], ',
                        'CAST([', COLUMN_NAME, '] AS DATE) AS [DATE] ',
                        'FROM [EDS].[EDS_CTL]'
                    ),
                    ' UNION ALL '
                )
                FROM INFORMATION_SCHEMA.COLUMNS
                WHERE TABLE_SCHEMA = 'EDS'
                  AND TABLE_NAME = 'EDS_CTL'
                  AND DATA_TYPE LIKE '%date%'
            )

            + '
        ) t
    )

    + ''</table>'';
';

EXEC sp_executesql
    @SQL,
    N'@HTML_OUT NVARCHAR(MAX) OUTPUT',
    @HTML_OUT = @HTML OUTPUT;

SELECT CONCAT(@HEADER, @STYLE, @HTML) AS body;
